S=[]
S.append(TITLE('TIN HỌC · CƠ SỞ DỮ LIỆU 1','CƠ SỞ DỮ LIỆU<br>VÀ HỆ QUẢN TRỊ CSDL','Dữ liệu, CSDL, hệ quản trị CSDL, chức năng của hệ QTCSDL, giao dịch, CSDL tập trung và phân tán, lợi ích, mô hình quan hệ: bảng – bản ghi – trường.',['CSDL','QTCSDL','giao dịch','quan hệ','phân tán']))
S.append(goals(c,B,['Phân biệt <b>tệp dữ liệu rời rạc</b> và <b>CSDL</b>; nêu lợi ích của CSDL.','Định nghĩa <b>CSDL</b> và <b>hệ QTCSDL</b>; kể tên các hệ phổ biến.','Nêu các <b>nhóm chức năng</b> của hệ QTCSDL, nhận biết chức năng qua tình huống.','Phân biệt <b>CSDL tập trung</b> và <b>phân tán</b>.','Gọi tên đúng <b>bảng, bản ghi, trường</b> trong mô hình quan hệ.'],['Vì sao cần CSDL','Hệ QTCSDL','Chức năng, giao dịch','Tập trung – phân tán','Mô hình quan hệ']))
