S.append(S2(c,B+' · 1','Khái niệm: dữ liệu – CSDL – hệ QTCSDL',card('Ba khái niệm',P('<b>Cơ sở dữ liệu (CSDL)</b>: tập hợp dữ liệu <b>có cấu trúc</b>, liên quan nhau, lưu trên thiết bị nhớ, phục vụ nhiều người / nhiều mục đích.','<b>Hệ quản trị CSDL (hệ QTCSDL)</b>: <b>phần mềm</b> để tạo, lưu trữ, cập nhật, truy xuất CSDL và kiểm soát việc truy cập.','<b>Hệ CSDL</b> = CSDL + hệ QTCSDL (+ người dùng, ứng dụng).','Ví dụ hệ QTCSDL: <b>MySQL, MariaDB, PostgreSQL, SQL Server, Oracle, SQLite</b>.')),svgbox_c1() if False else '<svg viewBox="0 0 520 250" style="width:100%"><g font-family="sans-serif" font-weight="800" font-size="20"><rect x="10" y="20" width="150" height="60" rx="10" fill="#C8E6C9" stroke="#2E7D32" stroke-width="3"/><text x="85" y="57" text-anchor="middle" fill="#0B2545">Người dùng</text><rect x="190" y="20" width="150" height="60" rx="10" fill="#FFF9C4" stroke="#F9A825" stroke-width="3"/><text x="265" y="57" text-anchor="middle" fill="#0B2545">Ứng dụng</text><rect x="100" y="110" width="320" height="50" rx="10" fill="#BBDEFB" stroke="#1565C0" stroke-width="3"/><text x="260" y="142" text-anchor="middle" fill="#0B2545">Hệ QTCSDL (phần mềm)</text><rect x="170" y="190" width="180" height="50" rx="10" fill="#E1BEE7" stroke="#6A1B9A" stroke-width="3"/><text x="260" y="222" text-anchor="middle" fill="#0B2545">CSDL (dữ liệu)</text><line x1="85" y1="80" x2="180" y2="110" stroke="#0B2545" stroke-width="3"/><line x1="265" y1="80" x2="265" y2="110" stroke="#0B2545" stroke-width="3"/><line x1="260" y1="160" x2="260" y2="190" stroke="#0B2545" stroke-width="3"/></g></svg>'+KEY('Người dùng không thao tác trực tiếp lên dữ liệu: mọi thứ đi qua <b>hệ QTCSDL</b>.')))
